import { SwiperContainer } from "swiper/element";

class AnnouncementBar extends HTMLElement {
  private swiperEl: SwiperContainer | null = null;
  private navNextButtons: NodeListOf<Element> | null = null;
  private navPrevButtons: NodeListOf<Element> | null = null;
  private resizeObserver: ResizeObserver | null = null;

  connectedCallback() {
    this.init();
    this.setupHeightMonitoring();
    this.triggerHeaderHeightUpdate();
  }

  disconnectedCallback() {
    this.cleanup();
    this.cleanupHeightMonitoring();
    this.triggerHeaderHeightUpdate();
  }

  init() {
    this.setUpSwiper();
    this.triggerHeaderHeightUpdate();
  }

  setUpSwiper() {
    const swiperEl = this.querySelector("swiper-container");

    if (!swiperEl) {
      return;
    }

    this.swiperEl = swiperEl as SwiperContainer;

    // Wait for swiper to be ready, then set up navigation
    this.swiperEl.addEventListener("swiperinit", () => {
      this.setUpCustomNav();
    });

    // If swiper is already initialized
    if (this.swiperEl.swiper) {
      this.setUpCustomNav();
    }
  }

  setUpCustomNav() {
    if (!this.swiperEl?.swiper) {
      return;
    }

    this.navNextButtons = this.querySelectorAll(".swiper-button-next");
    this.navPrevButtons = this.querySelectorAll(".swiper-button-prev");

    if (!this.navNextButtons.length || !this.navPrevButtons.length) {
      return;
    }

    // Add click handlers
    this.navNextButtons.forEach((button) => {
      button.addEventListener("click", this.handleNextClick.bind(this));
    });

    this.navPrevButtons.forEach((button) => {
      button.addEventListener("click", this.handlePrevClick.bind(this));
    });

    // Listen for swiper events to update navigation state
    this.swiperEl.addEventListener("swiperslidechange", () => {
      this.updateNavigationState();
    });

    // Initial state update
    this.updateNavigationState();
  }

  private handleNextClick = (e: Event) => {
    e.preventDefault();
    e.stopPropagation();
    this.swiperEl?.swiper.slideNext();
  };

  private handlePrevClick = (e: Event) => {
    e.preventDefault();
    e.stopPropagation();
    this.swiperEl?.swiper.slidePrev();
  };

  private updateNavigationState() {
    if (
      !this.swiperEl?.swiper ||
      !this.navNextButtons ||
      !this.navPrevButtons
    ) {
      return;
    }

    const swiper = this.swiperEl.swiper;

    // Update next button state
    this.navNextButtons.forEach((button) => {
      if (swiper.isEnd && !swiper.params.loop) {
        button.classList.add("swiper-button-disabled");
        (button as HTMLButtonElement).disabled = true;
      } else {
        button.classList.remove("swiper-button-disabled");
        (button as HTMLButtonElement).disabled = false;
      }
    });

    // Update prev button state
    this.navPrevButtons.forEach((button) => {
      if (swiper.isBeginning && !swiper.params.loop) {
        button.classList.add("swiper-button-disabled");
        (button as HTMLButtonElement).disabled = true;
      } else {
        button.classList.remove("swiper-button-disabled");
        (button as HTMLButtonElement).disabled = false;
      }
    });
  }

  private cleanup() {
    if (this.navNextButtons) {
      this.navNextButtons.forEach((button) => {
        button.removeEventListener("click", this.handleNextClick);
      });
    }

    if (this.navPrevButtons) {
      this.navPrevButtons.forEach((button) => {
        button.removeEventListener("click", this.handlePrevClick);
      });
    }
  }

  private setupHeightMonitoring() {
    this.resizeObserver = new ResizeObserver(() => {
      // Debounce the header height update to prevent conflicts
      this.triggerHeaderHeightUpdateDebounced();
    });
    this.resizeObserver.observe(this);
  }

  private cleanupHeightMonitoring() {
    if (this.resizeObserver) {
      this.resizeObserver.disconnect();
      this.resizeObserver = null;
    }
  }

  private triggerHeaderHeightUpdateDebounced() {
    // Use a longer delay than the header's own resize handler
    // to ensure the header handles its own resize first
    setTimeout(() => {
      this.triggerHeaderHeightUpdate();
    }, 50);
  }

  private triggerHeaderHeightUpdate() {
    // Find the header component and trigger its height calculation
    const headerComponent = document.querySelector(
      "uwp-header",
    ) as HTMLElement & { handleHeaderHeight?: () => void };

    if (headerComponent && headerComponent.handleHeaderHeight) {
      // Use requestAnimationFrame to ensure DOM updates are complete
      requestAnimationFrame(() => {
        headerComponent.handleHeaderHeight!();
      });
    }
  }
}

customElements.define("uwp-announcement-bar", AnnouncementBar);
